query.mssql:
if not exists(select 1 from [dbo].[Sungero_Docflow_Params] where [Key] = '{0}')
  insert [Sungero_Docflow_Params] ([Key],Value) values ('{0}', '{1}')
else UPDATE Sungero_Docflow_Params SET Value = '{1}' WHERE ([Key] = '{0}')

query.postgres:
do $$
begin
  if not exists(select 1 from Sungero_Docflow_Params where Key = '{0}')
  then
    insert into Sungero_Docflow_Params (Key, Value) values ('{0}', '{1}');
  else
    UPDATE Sungero_Docflow_Params SET Value = '{1}' WHERE (Key = '{0}');
  end if;
end$$;

query.mssql:
IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'temp_projectplanner')
BEGIN
  EXEC('
    UPDATE DirRX_Projec1_PrjctActivity
    SET DirRX_Projec1_PrjctActivity.ProjectPlan = temp_projectplanner.projectplan_name
    FROM temp_projectplanner, DirRX_Projec1_PrjctActivity
    WHERE temp_projectplanner.id = DirRX_Projec1_PrjctActivity.id;

    TRUNCATE TABLE temp_projectplanner
  ');
END;

IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'temp_projectplanner_projects')
BEGIN
  EXEC('
    UPDATE Sungero_Docflow_Project 
    SET Sungero_Docflow_Project.ProjectPlanDir_Project_DirRX = temp_projectplanner_projects.projectplan_name
    FROM temp_projectplanner_projects, Sungero_Docflow_Project
    WHERE temp_projectplanner_projects.id = Sungero_Docflow_Project.id;
    
    TRUNCATE TABLE temp_projectplanner_projects
  ');
END;

query.postgres:
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'temp_projectplanner')
  THEN
    BEGIN
      UPDATE DirRX_Projec1_PrjctActivity
      SET ProjectPlan = temp_projectplanner.projectplan_name
      FROM temp_projectplanner
      WHERE temp_projectplanner.id = DirRX_Projec1_PrjctActivity.id;

      TRUNCATE TABLE temp_projectplanner;
    END;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'temp_projectplanner_projects')
  THEN
    BEGIN
      UPDATE Sungero_Docflow_Project
      SET ProjectPlanDir_Project_DirRX = temp_projectplanner_projects.projectplan_name
      FROM temp_projectplanner_projects
      WHERE temp_projectplanner_projects.id = Sungero_Docflow_Project.id;

      TRUNCATE TABLE temp_projectplanner_projects;
    END;
  END IF;
END $$

query.mssql:
if not exists (select * from sysobjects where name='ResourceLinks')
    CREATE TABLE ResourceLinks (
   project_activity_id bigint NOT NULL,
   resource_id bigint NOT NULL,
   average_busy real NOT NULL
);

query.postgres:
CREATE TABLE IF NOT EXISTS ResourceLinks (
   project_activity_id bigint NOT NULL,
   resource_id bigint NOT NULL,
   average_busy real NOT NULL
);

query.mssql:
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='DirRX_PP_Modified_Plans')
    BEGIN;
        CREATE TABLE DirRX_PP_Modified_Plans (
            id bigint IDENTITY(1,1) PRIMARY KEY,
            plan_id bigint NOT NULL
        )
    END;

query.postgres:
CREATE TABLE IF NOT EXISTS DirRX_PP_Modified_Plans (
   id SERIAL PRIMARY KEY,
   plan_id bigint NOT NULL
);

INSERT INTO DirRX_PP_Modified_Plans (plan_Id)
SELECT @planId
WHERE NOT EXISTS (SELECT 1 FROM DirRX_PP_Modified_Plans WHERE plan_Id = @planId);
